import { API, graphqlOperation } from "aws-amplify";
import { expense_reports_graph } from "@/graphql/queries.js";
import VueApexCharts from "vue3-apexcharts";
import ColoumnChart from "@/components/Graph/ColoumnChart.vue";
import ExportGroupAndCat from "@/components/ExpensesManagement/ExpensePopups/ExportGroupAndCat.vue";
import SnackBar from "@/components/SnackBar.vue";
const FileSaver = require("file-saver");
import axios from "axios";
export default {
  components: {
    apexchart: VueApexCharts,
    ExportGroupAndCat,
    SnackBar,
    ColoumnChart
  },
  data() {
    return {
      formattedmonth: "",
      monthlyTotal: "0",
      formattedyear: "",
      selectedData: "",
      ExportreportDialog: false,
      datevalue1: "",
      SnackBarComponent: {},
      section_value: [],
      monthPicker: false,
      datedisplay: "",
      datedisplayMonth: "",
      yearfilter: new Date().getFullYear(),
      monthfilter: "",
      monthNames: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
      itemyears: [],
      updatekey: 0,
      chartOptions: {
        chart: {
          type: "bar",
          height: 180
        },
        series: [],
        xaxis: {
          categories: []
        },
        yaxis: {
          title: {
            text: "Amount"
          }
        },
        title: {
          text: "Expenses by Category",
          align: "left",
          margin: 10,
          offsetX: 0,
          offsetY: 0,
          floating: false,
          style: {
            fontSize: "18px",
            fontWeight: "bold",
            color: "#263238"
          }
        },
        dataLabels: {
          enabled: false
        },
        legend: {
          position: "right",
          offsetY: 40
        },
        plotOptions: {
          bar: {
            horizontal: false,
            columnWidth: "55%",
            endingShape: "rounded"
          }
        },
        fill: {
          type: "gradient",
          gradient: {
            shade: "light",
            type: "vertical",
            shadeIntensity: 0.25,
            gradientIntensity: 0.75,
            stops: [0, 100]
          }
        },
        stroke: {
          show: true,
          width: 2,
          colors: ["transparent"]
        },
        tooltip: {
          y: {
            formatter: function (val) {
              return "$ " + val;
            }
          }
        },
        grid: {
          row: {
            colors: ["transparent"],
            opacity: 0.5
          }
        },
        responsive: [{
          breakpoint: 480,
          options: {
            chart: {
              width: 200
            },
            legend: {
              position: "bottom"
            }
          }
        }]
      }
    };
  },
  mounted() {
    this.populateYearItems();
    this.setInitialFilters();
    this.get_next();
  },
  watch: {
    yearfilter() {
      this.monthfilter = "";
      this.updateMonthItems(this.yearfilter);
      this.updateDatedisplayMonth();
    },
    monthfilter() {
      this.updateDatedisplayMonth();
    }
  },
  methods: {
    exportreport() {
      this.selectedData = "MyCategory";
      this.ExportreportDialog = true;
      this.datevalue1 = this.datedisplay;
    },
    async download_item(url, types, MonthYear) {
      let firstName = this.$store.getters.GetUserObj?.organization?.organization_team_id;
      let fileNames = firstName ? firstName + "_" + (types == "MonthlyReport" ? MonthYear + "_" : "") + "Category" + ".xlsx" : "_" + (types == "MonthlyReport" ? MonthYear + "_" : "") + "Category" + ".xlsx";
      try {
        const response = await axios({
          url: url,
          method: "GET",
          responseType: "blob"
        });
        if (!response.data) {
          throw new Error("No data received from the server.");
        }
        const fileName = fileNames;
        const blob = new Blob([response.data], {
          type: response.headers["content-type"] || "application/octet-stream"
        });
        FileSaver.saveAs(blob, fileName);
      } catch (error) {
        // console.error("Error downloading the file:", error);
      }
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.ExportreportDialog = false;
      this.get_next();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    fecth_date() {
      const monthMap = {
        Jan: "01",
        Feb: "02",
        Mar: "03",
        Apr: "04",
        May: "05",
        Jun: "06",
        Jul: "07",
        Aug: "08",
        Sep: "09",
        Oct: "10",
        Nov: "11",
        Dec: "12"
      };

      // Add null checks and default values
      if (!this.monthfilter || !this.yearfilter) {
        const currentDate = new Date();
        this.monthfilter = this.monthNames[currentDate.getMonth()];
        this.yearfilter = currentDate.getFullYear();
      }
      this.formattedmonth = parseInt(monthMap[this.monthfilter], 10);
      this.formattedyear = parseInt(this.yearfilter, 10);
    },
    async get_next() {
      await this.fecth_date();
      var data = this.$store.getters.GetUserObj;

      // Add null check for user data
      if (!data || !data.organization || !data.organization.organization_id) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "User data not available",
          timeout: 5000,
          Top: true
        };
        return;
      }
      try {
        let result = await API.graphql(graphqlOperation(expense_reports_graph, {
          input: {
            organization_id: data.organization.organization_id,
            year: this.formattedyear,
            month: this.formattedmonth,
            action_type: "CATEGORY"
          }
        }));
        let resultdata = JSON.parse(result.data.expense_reports_graph);
        if (resultdata.Status == "SUCCESS") {
          let response = resultdata.data;
          if (resultdata.data.length > 0) {
            this.section_value = [];
            this.section_value = [{
              name: "Expenses",
              data: response
            }];
            this.updatekey++;
            this.monthlyTotal = resultdata.monthly_total || "0";
          } else {
            this.section_value = [];
            this.updatekey++;
            this.monthlyTotal = "0";
          }
        } else {
          this.section_value = [];
          this.updatekey++;
          this.monthlyTotal = "0";
        }
      } catch (error) {
        this.monthlyTotal = "0";
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "An error occurred",
          timeout: 5000,
          Top: true
        };
        this.section_value = [];
      }
    },
    selectMonth(month) {
      this.monthfilter = month;
    },
    closedialog() {
      this.monthPicker = false;
    },
    saveSelection() {
      this.datedisplay = this.monthfilter + " " + this.yearfilter;
      this.monthPicker = false;
      this.get_next();
    },
    isMonthDisabled(index) {
      const currentYear = new Date().getFullYear();
      const currentMonth = new Date().getMonth();
      if (this.yearfilter === currentYear && index > currentMonth) {
        return true;
      }
      return false;
    },
    populateYearItems() {
      const currentYear = new Date().getFullYear();
      this.itemyears = Array.from({
        length: 10
      }, (_, index) => currentYear - index);
    },
    setInitialFilters() {
      const currentYear = new Date().getFullYear();
      this.yearfilter = currentYear;
      this.updateMonthItems(currentYear);
      this.monthfilter = this.monthNames[new Date().getMonth()] || "Jan";
      this.updateDatedisplayMonth();
      this.datedisplay = this.datedisplayMonth || `${this.monthfilter} ${this.yearfilter}`;
    },
    updateMonthItems(year) {
      const currentYear = new Date().getFullYear();
      if (year === currentYear) {
        this.monthitems = this.monthNames.slice(0, new Date().getMonth() + 1);
      } else {
        this.monthitems = [...this.monthNames];
      }
    },
    updateDatedisplayMonth() {
      if (this.yearfilter && this.monthfilter) {
        this.datedisplayMonth = `${this.monthfilter} ${this.yearfilter}`;
      } else {
        const currentDate = new Date();
        this.datedisplayMonth = `${this.monthNames[currentDate.getMonth()]} ${currentDate.getFullYear()}`;
      }
    }
  }
};
